"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { roll } from "@/lib/0nlytype/roll"

const share = (n: number) => (Number.isFinite(n) ? Math.min(1, Math.max(0, n)) : 0)

type RingProps = Omit<React.ComponentProps<"span">, "children"> & {
  /** How much of the ring the arc covers, 0–1. */
  value: number
  /** Where the arc begins, 0–1 of the way round from the ring's start. */
  from?: number
  /** The end of the arc that carries the dot, or none. */
  head?: "end" | "start" | "none"
}

/**
 * One hairline ring with an arc drawn on it at stroke width, and a dot at one end of the arc: the calendar's ring
 * for what's to come, inked for what was had. Absolutely placed in a positioned box, square unless the box says
 * otherwise. The parent sets how much of a turn the ring spans (--ot-ring-sweep, 1 by default) and where it
 * starts (--ot-ring-start, 0deg is the top); --ot-ring-inset steps it in, --ot-ring-ink and --ot-ring-head colour it.
 * The arc glides between values at andante. Decorative: the words that say its value live elsewhere.
 */
function Ring({ value, from = 0, head = "end", className, style, ...props }: RingProps) {
  return (
    <span
      data-slot="ring"
      data-head={head === "none" ? undefined : head}
      aria-hidden="true"
      className={cn("ot-ring", className)}
      style={{ "--ot-ring-p": share(value), "--ot-ring-from": share(from), ...style } as React.CSSProperties}
      {...props}
    >
      {head === "none" ? null : <i className="ot-ring-head" />}
    </span>
  )
}

type RadialChartProps = Omit<React.ComponentProps<"figure">, "children"> & {
  /** One ring per entry, the first outermost. */
  data: { label: string; value: number }[]
  /** Names the chart for assistive tech, e.g. "Reading goals, 2026". */
  label: string
  /** What a closed ring means, shared by every series. */
  max?: number
  /** What the values count. The readout reads "of 100 pages". */
  unit?: string
  /** The series the number rests on; its dot carries the accent. Defaults to the first. */
  now?: number
  format?: (value: number) => string
  /** ring: full concentric rings, the number inside. horizon: half rings standing on a horizon, the number on it. */
  variant?: "ring" | "horizon"
  /** Pins the pointed-at look on the series the number is on; set on the root for documentation. */
  "data-force"?: string
}

const figures = new Intl.NumberFormat("en-GB")

/**
 * Progress against a shared maximum: one hairline ring per series, its arc inked as far as it has got,
 * and one very large number inside. Point at a ring or focus its name and that ring inks, the others step
 * back and the number rolls to it; leave and it rolls back to now.
 */
function RadialChart({ data, label, max = 100, unit, now = 0, format = figures.format, variant = "ring", className, style, ...props }: RadialChartProps) {
  const [shown, setShown] = React.useState(now)
  const [pointed, setPointed] = React.useState(false)
  const target = React.useRef(now)
  const value = React.useRef<HTMLSpanElement>(null)
  const face = React.useRef<HTMLDivElement>(null)
  const key = React.useRef<HTMLUListElement>(null)
  const top = max > 0 ? max : 100
  const many = data.length > 1

  function show(i: number, on = true) {
    setPointed(on)
    if (i === target.current || !value.current || !data[i]) return
    const dir = data[i].value > data[target.current].value ? 1 : -1
    target.current = i
    roll(value.current, () => setShown(i), "0.3em", dir)
  }

  // The ring nearest the pointer, by radius; the middle, where the number stands, keeps what's shown.
  function pick(e: React.PointerEvent) {
    const rings = face.current?.querySelectorAll<HTMLElement>(".ot-ring")
    if (!rings?.length) return
    const box = rings[0].getBoundingClientRect()
    const d = Math.hypot(e.clientX - (box.left + box.width / 2), e.clientY - (box.top + box.height / 2))
    let best = -1
    let gap = 14
    rings.forEach((r, i) => {
      const off = Math.abs(r.getBoundingClientRect().width / 2 - d)
      if (off < gap) [best, gap] = [i, off]
    })
    if (best >= 0) show(best)
  }

  const at = data[shown] ?? data[now]
  const of = `of ${format(top)}${unit ? ` ${unit}` : ""}`

  return (
    <figure
      data-slot="radial-chart"
      data-variant={variant}
      data-pointed={pointed || undefined}
      aria-label={label}
      className={cn("ot-radial", className)}
      style={{ "--n": data.length, ...style } as React.CSSProperties}
      {...props}
    >
      <div
        ref={face}
        data-slot="radial-chart-face"
        className="ot-radial-face"
        aria-hidden="true"
        onPointerMove={many ? pick : undefined}
        onPointerLeave={many ? () => !key.current?.contains(document.activeElement) && show(now, false) : undefined}
      >
        {data.map((d, i) => (
          <Ring key={d.label} value={d.value / top} data-shown={i === shown || undefined} style={{ "--i": i } as React.CSSProperties} />
        ))}
      </div>
      <figcaption data-slot="radial-chart-read" className="ot-radial-read">
        <span ref={value} className="ot-radial-value">
          {at ? format(at.value) : ""}
        </span>
        <span className="ot-radial-words">
          <span className="ot-radial-name">{at?.label}</span>
          <span className="ot-radial-of">{of}</span>
        </span>
      </figcaption>
      {many ? (
        <ul
          ref={key}
          data-slot="radial-chart-key"
          className="ot-radial-key"
          onPointerLeave={() => !key.current?.contains(document.activeElement) && show(now, false)}
          onBlur={(e) => !key.current?.contains(e.relatedTarget) && show(now, false)}
        >
          {data.map((d, i) => (
            <li key={d.label}>
              <button type="button" data-shown={i === shown || undefined} onPointerEnter={() => show(i)} onFocus={() => show(i)}>
                <span>{d.label}</span> <span className="ot-radial-key-value">{format(d.value)}</span>
                <span className="ot-sr"> {of}</span>
              </button>
            </li>
          ))}
        </ul>
      ) : null}
    </figure>
  )
}

export { RadialChart, Ring, type RadialChartProps, type RingProps }

@layer components {
  /* ── ot-ring ── one hairline ring with an arc inked on it and a dot at one end. The calendar's vocabulary: a pencil
     ring for what's to come, ink for what was had. Both strokes are inset box-shadows cut by a conic mask (as the dot
     calendar sweeps its days), so they stay one hairline and one stroke at any size. The parent sets the span of a turn
     (--ot-ring-sweep, 1) and where it starts (--ot-ring-start, 0deg is the top, clockwise); --ot-ring-inset steps a
     ring in, --ot-ring-ink, --ot-ring-track and --ot-ring-head colour it. The timer and the pie chart stand on it. */
  @property --ot-ring-p { syntax: "<number>"; inherits: true; initial-value: 0; }
  @property --ot-ring-from { syntax: "<number>"; inherits: true; initial-value: 0; }
  .ot-ring {
    --ot-ring-p: 0; --ot-ring-from: 0;
    position: absolute; inset: var(--ot-ring-inset, 0); border-radius: 50%; pointer-events: none;
    transition: --ot-ring-p var(--ot-andante) var(--ot-exhale), --ot-ring-from var(--ot-andante) var(--ot-exhale);
  }
  .ot-ring::before, .ot-ring::after { content: ""; position: absolute; inset: 0; border-radius: 50%; }
  .ot-ring::before {
    box-shadow: inset 0 0 0 var(--ot-hairline) var(--ot-ring-track, var(--ot-rule-strong));
    mask: conic-gradient(from var(--ot-ring-start, 0deg), #000 calc(var(--ot-ring-sweep, 1) * 1turn), #0000 0);
  }
  .ot-ring::after {
    box-shadow: inset 0 0 0 var(--ot-stroke) var(--ot-ring-ink, var(--ot-ink));
    mask: conic-gradient(from calc(var(--ot-ring-start, 0deg) + var(--ot-ring-from) * var(--ot-ring-sweep, 1) * 1turn), #000 calc(var(--ot-ring-p) * var(--ot-ring-sweep, 1) * 1turn), #0000 0);
    transition: box-shadow var(--ot-allegro) var(--ot-exhale);
  }
  /* The dot rides the arc's end, its centre on the stroke's centre line. */
  .ot-ring-head { position: absolute; top: 0; left: 50%; inline-size: 0; block-size: 50%; transform-origin: 50% 100%; rotate: calc(var(--ot-ring-start, 0deg) + (var(--ot-ring-from) + var(--ot-ring-p)) * var(--ot-ring-sweep, 1) * 1turn); }
  .ot-ring[data-head="start"] > .ot-ring-head { rotate: calc(var(--ot-ring-start, 0deg) + var(--ot-ring-from) * var(--ot-ring-sweep, 1) * 1turn); }
  .ot-ring-head::after {
    content: ""; position: absolute; top: calc(var(--ot-stroke) / 2); left: 50%; inline-size: var(--ot-dot); block-size: var(--ot-dot); border-radius: 50%; translate: -50% -50%;
    background: var(--ot-ring-head, var(--ot-ink));
    transition: background-color var(--ot-allegro) var(--ot-exhale), scale var(--ot-moderato) var(--ot-spiccato);
  }
  @media (forced-colors: active) {
    .ot-ring::before { box-shadow: inset 0 0 0 var(--ot-hairline) GrayText; }
    .ot-ring::after { box-shadow: inset 0 0 0 var(--ot-stroke) CanvasText; }
    .ot-ring-head::after { background: Highlight; }
  }

  /* ── ot-radial ── progress against one maximum, from the dot calendar: a hairline ring per series, the arc inked as
     far as it has got, and one very large number inside it. Pointing at a ring, or its name, inks it and steps the
     others back to pencil; the number rolls to it and the accent dot moves to its ring. */
  .ot-radial {
    --ot-radial-gap: var(--ot-space-4);
    margin: 0; display: grid; grid-template-columns: minmax(0, 1fr); inline-size: min(100%, var(--ot-radial-size, 20rem)); row-gap: var(--ot-space-5); container-type: inline-size;
  }
  .ot-radial-face { grid-area: 1 / 1; position: relative; aspect-ratio: 1; }
  .ot-radial .ot-ring { --ot-ring-inset: calc(var(--i, 0) * var(--ot-radial-gap)); }
  .ot-radial .ot-ring[data-shown] { --ot-ring-head: var(--ot-accent); }
  .ot-radial:is([data-pointed], [data-force~="hover"]) .ot-ring:not([data-shown]) { --ot-ring-ink: var(--ot-rule-strong); --ot-ring-head: var(--ot-rule-strong); --ot-ring-track: var(--ot-rule); }
  .ot-radial-face { cursor: crosshair; }

  /* The number stands in the middle, as large as the innermost ring allows: SPECTRA's scale against the small print. */
  .ot-radial-read {
    grid-area: 1 / 1; place-self: center; display: grid; justify-items: center; row-gap: var(--ot-space-2); max-inline-size: calc(100% - 2 * var(--n, 1) * var(--ot-radial-gap) - var(--ot-space-5));
    text-align: center; pointer-events: none;
  }
  .ot-radial-value {
    display: inline-block; font-size: clamp(var(--ot-f), calc(34cqi - var(--n, 1) * 3cqi), var(--ot-fff)); line-height: 0.9; letter-spacing: var(--ot-ff-tr); font-weight: 200;
    color: var(--ot-ink); font-variant-numeric: tabular-nums lining-nums; white-space: nowrap;
  }
  .ot-radial-words { display: grid; justify-items: center; font-size: var(--ot-pp); line-height: var(--ot-pp-lh); letter-spacing: var(--ot-pp-tr); }
  .ot-radial-name { font-weight: 500; color: var(--ot-ink); }
  .ot-radial-of { color: var(--ot-pencil); }

  /* The key names each ring, outermost first. Pointing at a name, or focusing it, inks its ring. */
  .ot-radial-key { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--ot-space-2) var(--ot-space-5); margin: 0; padding: 0; list-style: none; }
  .ot-radial-key button {
    appearance: none; border: 0; margin: 0; padding: var(--ot-space-1) 0; background: none; font: inherit; cursor: crosshair;
    font-size: var(--ot-pp); line-height: var(--ot-pp-lh); letter-spacing: var(--ot-pp-tr); color: var(--ot-pencil);
    transition: color var(--ot-allegro) var(--ot-exhale);
  }
  .ot-radial-key-value { color: var(--ot-graphite); font-variant-numeric: tabular-nums; transition: color var(--ot-allegro) var(--ot-exhale); }
  .ot-radial-key button:is(:hover, :focus-visible, [data-shown]) { color: var(--ot-ink); }
  .ot-radial-key button:is(:hover, :focus-visible, [data-shown]) .ot-radial-key-value { color: var(--ot-ink); }

  /* horizon: the Eclipse. Half rings stand on a horizon that runs past them, and everything else is said below it:
     the number sits on the line, its words under the line. Right to left, the arcs rise from the right. */
  .ot-radial[data-variant="horizon"] { --ot-ring-sweep: 0.5; --ot-ring-start: -90deg; grid-template-rows: auto auto auto; row-gap: 0; padding-inline: var(--ot-space-5); inline-size: min(100%, calc(var(--ot-radial-size, 20rem) + 2 * var(--ot-space-5))); }
  .ot-radial[data-variant="horizon"] > .ot-radial-face { aspect-ratio: 2; }
  .ot-radial[data-variant="horizon"] .ot-ring { inset-block-end: auto; aspect-ratio: 1; }
  .ot-radial[data-variant="horizon"] > .ot-radial-face::after { content: ""; position: absolute; inset-inline: calc(-1 * var(--ot-space-5)); inset-block-end: 0; block-size: var(--ot-hairline); background: var(--ot-rule-strong); }
  .ot-radial[data-variant="horizon"]:is([dir="rtl"], [dir="rtl"] *) > .ot-radial-face { scale: -1 1; }
  .ot-radial[data-variant="horizon"] > .ot-radial-read { grid-row: 1 / span 2; place-self: stretch; grid-template-rows: subgrid; max-inline-size: none; row-gap: 0; }
  .ot-radial[data-variant="horizon"] .ot-radial-value { align-self: end; justify-self: center; font-size: clamp(var(--ot-mf), calc(26cqi - var(--n, 1) * 3cqi), var(--ot-fff)); line-height: 1; text-box: trim-end cap alphabetic; }
  .ot-radial[data-variant="horizon"] .ot-radial-words { padding-block-start: var(--ot-space-3); }
  /* No row gap on the horizon: the subgrid would push the number half a gap below the line. The key keeps its distance. */
  .ot-radial[data-variant="horizon"] > .ot-radial-key { margin-block-start: var(--ot-space-5); }
}
